with with_gaps as (select *, case when lag(paid_at) over (partition by order_id order by paid_at, id) is null or paid_at > lag(paid_at) over (partition by order_id order by paid_at, id) + interval 7 days then 1 else 0 end as is_new_burst from payments), sessions_payments as (select *, sum(is_new_burst) over (partition by order_id order by paid_at, id rows between unbounded preceding and current row) as session_no from with_gaps) select id, method, amount, status from sessions_payments;
